'use client'
import Page from "@/components/Pages";
import { Hero, Service, Tech } from "@/components/Contents";
import { useContent } from "@/hooks/useContent";
import Loading from './loading'
import LiquidBanner from "@/components/LiquidBanner";
import SideNav, { SideNavSection } from "@/components/SideNav";
import { useEffect, useState } from "react";
// Fallback list of images in public/img/backgrounds, generated by
// scripts/generate-backgrounds.mjs; used when the R2 list can't be fetched.
import localBackgrounds from "@/generated/backgrounds.json";
const sections: SideNavSection[] = [
  { id: 'hero-banner', label: 'home', dark: true },
  { id: 'service', label: 'service' },
  { id: 'tech', label: 'tech' },
]

const Home = () => {
  const { isLoading } = useContent()
  // null until the list arrives, so the banner sets up once with the images
  const [backgrounds, setBackgrounds] = useState<string[] | null>(null)

  useEffect(() => {
    fetch('/api/backgrounds')
      .then((res) => res.ok ? res.json() : Promise.reject(res.status))
      .then((urls: string[]) => setBackgrounds(urls.length ? urls : localBackgrounds))
      .catch((error) => {
        console.warn('Falling back to local banner images:', error)
        setBackgrounds(localBackgrounds)
      })
  }, [])

  return !isLoading ? (
    <main className="flex-row min-h-screen items-center justify-center ">
      {/* id is used by the Menu to invert its colours once scrolled past */}
      <div id="hero-banner" className="relative overflow-hidden text-white">
        {backgrounds && <LiquidBanner className="absolute inset-0" images={backgrounds} />}
        <div className="relative z-10">
          <Page sectionName="hero">
            <Hero />
          </Page>
        </div>
      </div>
      <Page sectionName="service">
        <Service />
      </Page>
      <Page sectionName="tech">
        <Tech />
      </Page>
      <SideNav sections={sections} />
    </main>
  ) : (
      <Loading />
  )
}

export default Home